from agent import *from models.products import *def getexcerpt(txtlist):    excerpt = ''    txtlist = [o.string().strip() for o in txtlist]    for line in txtlist:        excerpt += ' ' + line        if re_search_once("([!?.])$", line) and len(line) > 100:            break    excerpt = re.compile("\s+").sub(' ', excerpt)    return excerpt.strip()def process_frontpage(data: Response, context: dict[str, str], session: Session):    for rev in data.xpath("//li[contains(@class, 'list-group-item')]"):        url = rev.xpath(".//a//@href").string()        title = rev.xpath(".//a//text()").string(multiple=True)        rating = rev.xpath(".//div[contains(@class, 'col-md-2')][1]//text()").string()        category = rev.xpath(".//div[contains(@class, 'col-md-2')][2]//text()").string(multiple=True)        date = rev.xpath(".//div[contains(@class, 'col-md-2')][3]//text()").string(multiple=True)        session.queue(Request(url, use='curl'), process_review, dict(url=url, title=title, category=category, date=date, rating=rating))def process_review(data: Response, context: dict[str, str], session: Session):    product = Product()    product.name = context['title']    product.url = context['url']    product.category = 'Games|' + context['category']    product.ssid = re_search_once('CHEATfactor-(\d+)', context['url'])    if not(product.ssid):        product.ssid = context['url'].split('/reviews/')[-1].split('.asp')[0]    review = Review()    review.type = 'pro'    review.title = context['title']    review.url = context['url']    review.ssid = product.ssid    review.date = context['date']    author = data.xpath("//div[@class='revheadReviewer']//em//following-sibling::text()").string()    if author:        author = author.split('by:')[-1]        review.authors.append(Person(name=author, ssid=author))    excerpt = data.xpath("//div[@class='revPara']/p/span[regexp:test(text(),'What it is')]/following-sibling::node()/descendant-or-self::text()").string(multiple=True)    if not(excerpt):        excerpt = data.xpath("/descendant::div[@class='revPara'][1]/p[last()]//text()").string(multiple=True)    if not(excerpt):        excerpt = data.xpath("/descendant::td[@class='opentext'][1]/p[last()]//text()").string(multiple=True)    if not(excerpt):        excerpt = data.xpath("/descendant::span[@class='blacktext12']/following-sibling::p//text()").string(multiple=True)    txtlist = data.xpath("//tr//td[@class='white11']//p[@class='header']//following-sibling::p//text()")    if not(excerpt) and txtlist:        excerpt = getexcerpt(txtlist)    if excerpt:        review.add_property(type='excerpt', value=excerpt)    conclusion = data.xpath("//div[@class='revPara']/p/span[regexp:test(text(),'Conclusion')]/following-sibling::node()/descendant-or-self::text()").string(multiple=True)    if not(conclusion):        conclusion = data.xpath("/descendant::div[@class='revPara'][last()]/p[last()]//text()").string(multiple=True)    if not(conclusion):        conclusion = data.xpath("/descendant::td[@class='opentext'][last()]/p[last()]//text()").string(multiple=True)    if not(conclusion):        conclusion = data.xpath("//td[@class='factorbox']//p[@class='title']//following-sibling::p//text()").string(multiple=True)    if conclusion:        review.add_property(type='conclusion', value=conclusion)    for pro in data.xpath("//div[@class='revPara'][regexp:test(normalize-space(.),'What Works','i')]/p[not(@class) and not(regexp:test(normalize-space(.),'^Conclusion'))]"):        line = pro.xpath("descendant::text()").string(multiple=True)        if line:            review.add_property(type='pros', value=line)    for con in data.xpath("//div[@class='revPara'][regexp:test(normalize-space(.),'What Doesn.t work','i')]/p[not(@class) and not(regexp:test(normalize-space(.),'^Conclusion'))]"):        line = con.xpath("descendant::text()").string(multiple=True)        if line:            review.add_property(type='cons', value=line)    ratetxt = data.xpath("//div[@class='ratingOverall']/span/text()").string()    if ratetxt:        rate = re_search_once('(\d\.?\d?)\/', ratetxt)        name = data.xpath("//div[@class='ratingOverall']/text()").string()        if rate:            if 'Overall' in name:                review.grades.append(Grade(name=name, type='overall', value=float(rate), best=10.0))            else:                review.grades.append(Grade(name=name, value=float(rate), best=10.0))    for g in data.xpath("//div[regexp:test(@class,'rating.*S')]"):        value = g.xpath("text()").string()        name = g.xpath("preceding-sibling::div[1]/text()").string()        if name and value:            if 'Overall' in name:                review.grades.append(Grade(name=name, type='overall', value=float(value), best=10.0))            else:                review.grades.append(Grade(name=name, value=float(value), best=10.0))    for g in data.xpath("//tr[count(td[regexp:test(@class,'openbold')])=2]"):        valuetxt = g.xpath("td[2]//text()").string()        name = g.xpath("td[1]//text()").string()        description = g.xpath("following::tr[1]//text()").string(multiple=True)        if name and valuetxt:           value = re_search_once('^(\d.?\d?)\/', valuetxt)           if 'Overall' in name:               review.grades.append(Grade(name=name, type='overall', value=float(value), best=10.0, description=description))           else:               review.grades.append(Grade(name=name, value=float(value), best=10.0, description=description))    ratetxt = data.xpath("//td[@class='revheader' and regexp:test(normalize-space(.),'CHEAT')]/following-sibling::td//text()").string()    if ratetxt:        rate = re_search_once('(\d\.?\d?)\/', ratetxt)        if rate:            if 'Overall' in name:                review.grades.append(Grade(name=name, type='overall', value=float(rate), best=10.0))            else:                review.grades.append(Grade(name='CHEATfactor', value=float(rate), best=10.0))    for grade in data.xpath("//td[@class='white11']//table//tr"):        name = grade.xpath(".//td[@class='titlewhite']//text()").string()        score = grade.xpath(".//td[@class='titlewhite']//following-sibling::td//img//@src").string()        if name and score:            name = name.split(":")[0]            score = score.split('/rate')[-1].split('.jpg')[0]            if 'Overall' in name:                review.grades.append(Grade(name=name, type='overall', value=float(score), best=10.0))            else:                review.grades.append(Grade(name=name, value=float(score), best=10.0))    cheat_factor = data.xpath("//td[@class='white11']//table//tr//td[@class='title2']//following-sibling::td//img//@src").string()    if cheat_factor:        cheat_factor = cheat_factor.split('/rate')[-1].split('.jpg')[0]        review.grades.append(Grade(name='CHEAT factor', value=float(cheat_factor), best=10.0))    user_rat = data.xpath("//span[@class='title2']//parent::td//following-sibling::td//img//@src").string()    if user_rat:        user_rat = user_rat.split('/rate')[-1].split('.jpg')[0]        review.grades.append(Grade(name='User Rating', value=float(user_rat), best=10.0))     if excerpt or conclusion:        product.reviews.append(review)        session.emit(product)def run(context: dict[str, str], session: Session):    session.queue(Request('https://www.cheathappens.com/reviews_index.asp?letter=ALL&pl=0', use='curl'), process_frontpage, {})